function PopularSidebar({mobile=false}:{mobile?:boolean}){const [posts,setPosts]=useState<Post[]>([]),[loading,setLoading]=useState(true),[error,setError]=useState(false),[retry,setRetry]=useState(0);useEffect(()=>{let live=true;setLoading(true);setError(false);api('/api/posts?sort=popular&preview=sidebar').then(d=>{if(live)setPosts(d.posts.slice(0,mobile?3:7))}).catch(()=>{if(live)setError(true)}).finally(()=>{if(live)setLoading(false)});return()=>{live=false}},[retry,mobile]);const headingId=mobile?"mobile-popular-title":"sidebar-popular-title";return <section className={"side-card popular-sidebar"+(mobile?" mobile-popular":"")} aria-labelledby={headingId}><h2 id={headingId}><a href="/?sort=popular"><span><Flame/>인기글</span><ArrowUpRight aria-hidden="true"/></a></h2>{loading?<p role="status">인기글을 불러오는 중…</p>:error?<div><p role="alert">인기글을 불러오지 못했어요.</p><button className="secondary" onClick={()=>setRetry(v=>v+1)}>다시 불러오기</button></div>:posts.length?<ol>{posts.map((p,i)=><li key={p.id}><a href={'/post/'+p.id} title={p.title}><span className="popular-rank">{i+1}</span><span className="popular-title">{p.title}</span>{p.comments>0&&<span className="popular-comments" aria-label={'댓글 '+p.comments+'개'}>[{p.comments}]</span>}</a></li>)}</ol>:<p>아직 인기글이 없어요.</p>}</section>}
