r/>© 2026 SECRET AGIT</div></aside><main className="main">{children}</main><aside className="right-rail"><section className="side-card"><div className="mini-label">HELLO, THERE</div><h2 style={{fontSize:19,marginTop:12}}>오늘 뭐가 웃겼나요?</h2><p>혼자 보기 아까운 짤 하나,<br/>별것 아닌 하루의 이야기 하나.</p><a className="primary" href="/write"><PenLine/>이야기 올리기</a></section><PopularSidebar/><div className="tiny-footer">{brand.name} · 커뮤니티<br/>{brand.url?new URL(brand.url).hostname:'도메인 연결 준비 중'}</div></aside></div><footer>{brand.name} &nbsp; · &nbsp; 오늘의 웃음을 모으는 곳</footer></>}
function FeedPost({post:p}:{post:Post}){const photos=p.images|| (p.thumbnail?[p.thumbnail]:[]);return <a className="post-row" href={'/post/'+p.id}><div className="post-card-top"><span className="tag">{p.category}</span><div className="post-author"><span title={p.nickname}>{p.nickname}</span><time dateTime={new Date(p.created_at).toISOString()}>{new Date(p.created_at).toLocaleDateString('ko-KR')}</time></div></div><h2 title={p.title}>{p.title}</h2>{photos.length>0&&<div className={'post-gallery '+(photos.length>2?'has-more-photos':photos.length===1?'one-photo':'two-photos')}>{photos.slice(0,2).map((src,i)=><img className="post-gallery-main" key={src} src={src} alt={'첨부 사진 '+(i+1)} loading="lazy" draggable={false}/>)}{photos.length>2&&<div className="post-gallery-grid">{photos.slice(2,6).map((src,i)=><div className="post-gallery-small" key={src}><img src={src} alt={'첨부 사진 '+(i+3)} loading="lazy" draggable={false}/>{i===3&&(p.imageCount||0)>6&&<span className="post-gallery-count">+{p.imageCount!-6}</span>}</div>)}</div>}</div>}{p.excerpt&&<p className="post-excerpt">{p.excerpt}</p>}<div className="meta"><span><ThumbsUp/>{p.likes}</span><span><MessageCircle/>{p.comments}</span><span><Eye/>{p.views}</span></div></a>}
export default function Community(){const [posts,setPosts]=useState<Post[]>([]);const [board,setBoard]=useState('전체');const [sort,setSort]=useState('latest');const [q,setQ]=useState('');const [loading,setLoading]=useState(true);const [error,setError]=useState('');const [offset,setOffset]=useState(0);const [more,setMore]=useState(false);useEffect(()=>{const p=new URLSearchParams(location.search);setBoard(p.get('board')||'전체');setSort(p.get('sort')||'latest');setQ(p.get('q')||'');},[]);useEffect(()=>{let live=true;setLoading(true);setError('');api('/api/posts?'+new URLSearchParams({board,sort,q,offset:String(offset)})).then(d=>{if(live){setPosts(old=>offset?[...old,...d.posts]:d.posts);setMore(d.more);}}).catch(e=>{if(live)setError(e.message)}).finally(()=>{if(live)setLoading(false)});return()=>{live=false}},[board,sort,q,offset]);return <Shell active={board} onBoard={v=>{setBoard(v);setOffset(0)}} onSearch={v=>{setQ(v);setOffset(0)}}><div className="page-head"><div><h1>{q?'검색 결과':sort==='popular'?'인기글':board==='전체'?'전체 이야기':board}</h1><p className="subtext">{q?'“'+q+'”에 대한 이야기':'웃긴 건 같이 보자. 오늘도 가볍게, 한바탕.'}</p></div><a className="primary" href="/write"><PenLine/>글쓰기</a></div><div className="welcome"><img className="welcome-mascot" src="/images/welcome-bird.png" alt="" width={64} height={64} draggable={false}/><div><strong>새로 모이는 우리들의 아지트</strong><p>유머부터 소소한 일상까지, 첫 이야기를 기다리고 있어요.</p></div></div><PopularSidebar mobile/><section className="feed"><div className="feed-tabs"><Tabs value={sort} onValueChange={v=>{setSort(v);setOffset(0)}}><TabsList variant="line"><TabsTrigger value="latest">최신순</TabsTrigger><TabsTrigger value="popular"><Flame/>인기글</TabsTrigger></TabsList></Tabs><span className="feed-count">지금, 올라오는 이야기</span></div><div className="notice-row"><b>안내</b>유튜브 링크 · 사진 · 동영상 첨부를 지원해요.</div>{error?<div className="empty"><p role="alert">{error}</p><button className="secondary" onClick={()=>location.reload()}>다시 불러오기</button></div>:posts.length?posts.map(p=><FeedPost key={p.id} post={p}/>):!loading?<div className="empty"><MessagesSquare/><h2>{q?'아직 일치하는 이야기가 없어요':sort==='popular'?'아직 인기글 조건을 충족한 글이 없어요':'아직은 조용한 아지트'}</h2><p>{q?'다른 검색어로 찾아보세요.':'첫 번째 웃음을 남겨 주세요.\n글도, 사진도, 짤도 좋아요.'}</p><a className="primary" href="/write"><PenLine/>첫 이야기 쓰기</a></div>:null}{loading&&<div className="loading" role="status">이야기를 불러오는 중…</div>}{more&&!loading&&<button className="secondary load-more" onClick={()=>setOffset(posts.length)}>더 보기</button>}</section></Shell>}

'use client';
import {useState,useEffect} from 'react';import {ExternalLink,Link2} from 'lucide-react';import type {Block} from '@/lib/models';import {api} from './community';
type Preview={id:string;title:string;description:string;image_id:string|null};
export function LinkCard({url,create=false}:{url:string;create?:boolean}){const [preview,setPreview]=useState<Preview|null>(null);useEffect(()=>{let live=true;api<{preview:Preview|null}>(create?'/api/previews':'/api/previews?url='+encodeURIComponent(url),create?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url})}:undefined).then(d=>{if(live)setPreview(d.preview)}).catch(()=>{});return()=>{live=false}},[url,create]);let host='링크';try{host=new URL(url).hostname}catch{}return <a className="link-card" href={url} target="_blank" rel="noopener noreferrer" draggable={false}>{preview?.image_id?<img src={'/api/previews/'+preview.id+'/image'} alt="" loading="lazy" draggable={false}/>:<span className="link-card-icon"><Link2/></span>}<span className="link-card-copy"><small>{host}</small><strong>{preview?.title||host}</strong>{preview?.description&&<span>{preview.description}</span>}<small>원문 보기 <ExternalLink style={{display:'inline',width:12}}/></small></span></a>}
export function Youtube({videoId,autoplay=false}:{videoId:string;autoplay?:boolean}){return <div className="youtube-frame"><iframe src={'https://www.youtube-nocookie.com/embed/'+encodeURIComponent(videoId)+'?autoplay='+(autoplay?'1&mute=1':'0')} title="YouTube 동영상" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture; fullscreen" allowFullScreen referrerPolicy="strict-origin-when-cross-origin" loading="lazy"/></div>}
export function BodyContent({blocks,autoplay=false,createPreviews=false}:{blocks:Block[];autoplay?:boolean;createPreviews?:boolean}){return <>{blocks.map((b,i)=>b.type==='text'?<p key={i}>{b.text}</p>:b.type==='image'?<img key={i} src={'/api/media/'+b.id} alt={'첨부 이미지 '+(i+1)} draggable={false} loading="lazy"/>:b.type==='video'?<video key={i} src={'/api/media/'+b.id} controls controlsList="nodownload noremoteplayback" disablePictureInPicture playsInline preload="metadata" autoPlay={autoplay} muted={autoplay} onContextMenu={e=>e.preventDefault()}/>:b.type==='youtube'?<Youtube key={i} videoId={b.videoId} autoplay={autoplay}/>:<LinkCard key={b.url} url={b.url} create={createPreviews}/>)}</>}

