async function run(items:{node:HTMLElement;value:File|string;kind?:'image'|'video'}[]){if(uploadLock.current){setError('현재 첨부 저장이 끝나면 다시 붙여넣어 주세요.');return}uploadLock.current=true;setUploading(true);setError('');try{for(const item of items){if(!item.node.isConnected)continue;item.node.dataset.status='pending';item.node.textContent='이미지를 저장하고 있어요…';await upload(item.node,item.value,item.kind)}setStatus('첨부 처리가 끝났어요. 실패 표시가 있는지 확인해 주세요.')}finally{uploadLock.current=false;setUploading(false)}}
function files(items:File[]){if(!editor.current||uploadLock.current)return;const current=editor.current.querySelectorAll('img,video,[data-status]').length;if(current+items.length>20){setError('첨부는 최대 20개까지 첨부할 수 있어요.');return}const frag=document.createDocumentFragment();const tasks=items.map(value=>{const node=document.createElement('span');node.className='failed-media';node.style.display='block';node.contentEditable='false';node.dataset.status='pending';node.textContent='첨부 저장 준비 중…';frag.append(node);return {node,value}});insertFragment(editor.current,frag);void run(tasks)}
async function submit(){setError('');if(!editor.current||!ready)return;if(!signedIn){setError('로그인 후 등록해 주세요.');return}if(!title.trim()||!nickname.trim()){setError('제목과 닉네임을 입력해 주세요.');return}if(editor.current.querySelector('[data-status]')){setError('아직 저장되지 않은 이미지가 있어요. 재시도하거나 빼고 등록해 주세요.');return}const blocks=readBlocks(editor.current);if(!blocks.length){setError('본문이나 사진을 넣어 주세요.');return}setBusy(true);try{const d=await api(editId?'/api/posts/'+editId:'/api/posts',{method:editId?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title,nickname,category,source,blocks})});saved.current=true;if(!editId){try{localStorage.removeItem('secretagit-draft')}catch{}}location.href='/post/'+d.id}catch(e){setError((e as Error).message);setBusy(false)}}
useEffect(()=>{const ctx=(document as Document & {modelContext?:{registerTool:(tool:unknown,options:unknown)=>Promise<void>|void}}).modelContext;if(!ctx)return;const life=new AbortController();try{void Promise.resolve(ctx.registerTool({name:'stage_community_draft',description:'제목과 본문을 편집기에 준비합니다. 게시하지 않습니다.',inputSchema:{type:'object',properties:{title:{type:'string'},text:{type:'string'}},required:['title','text'],additionalProperties:false},annotations:{readOnlyHint:false},execute:(input:unknown)=>{const d=input as {title?:unknown;text?:unknown};if(typeof d.title!=='string'||d.title.length>120||typeof d.text!=='string'||d.text.length>30000)throw new Error('Invalid draft');if(!editor.current||uploadLock.current)throw new Error('Editor busy');setTitle(d.title);renderBlocks(editor.current,[{type:'text',text:d.text}]);dirty.current=true;return {staged:true,published:false}}},{signal:life.signal})).catch(()=>{})}catch{}return()=>life.abort()},[]);
return <Shell><a className="back" href="/"><ArrowLeft/>이야기 목록</a><div className="panel"><h1 className="composer-heading">{editId?'이야기 수정':'이야기 쓰기'}</h1><p className="subtext composer-intro">오늘의 웃음을 같이 나눠요.</p>{signedIn===false&&<div className="status">등록과 첨부 저장은 로그인이 필요해요. <a style={{textDecoration:'underline'}} href={'/signin-with-chatgpt?return_to='+encodeURIComponent('/write'+(editId?'?edit='+editId:''))} target="_top">ChatGPT로 로그인</a></div>}<div className="field"><label>게시판</label><RadioGroup value={category} onValueChange={v=>{setCategory(v);dirty.current=true}} className="composer-boards">{['유머','짤','영상','이슈','자유','경제'].map(b=><label key={b} className="composer-board-option"><RadioGroupItem value={b}/><span>{b}</span></label>)}</RadioGroup></div><input className="field-input title-input" aria-label="제목" placeholder="제목을 입력해 주세요" maxLength={120} value={title} onChange={e=>{setTitle(e.target.value);dirty.current=true}}/><div className="editor-toolbar"><button className="secondary" type="button" disabled={uploading||!signedIn||!ready} onClick={()=>file.current?.click()}><ImagePlus/>사진 · 영상 첨부</button><small>사진 10MB · MP4/WebM 50MB · 최대 20개</small><input ref={file} hidden type="file" accept="image/jpeg,image/png,image/gif,image/webp,image/avif,video/mp4,video/webm" multiple onChange={e=>{files(Array.from(e.target.files||[]));e.target.value=''}}/></div><div ref={editor} className="editor" contentEditable={!busy&&ready} suppressContentEditableWarning role="textbox" aria-label="본문" aria-multiline="true" data-placeholder="글과 사진, 유튜브 주소를 붙여넣어 주세요. 동영상 파일도 첨부할 수 있어요." onInput={()=>dirty.current=true} onBlur={e=>{if(editor.current&&!editor.current.contains(e.relatedTarget as Node)&&!uploadLock.current&&!editor.current.querySelector('[data-status]')){const blocks=readBlocks(editor.current);renderBlocks(editor.current,blocks);setPreviewLinks(blocks.filter((b):b is Extract<Block,{type:'link'}>=>b.type==='link').map(b=>b.url).slice(0,10))}}} onPaste={e=>{e.preventDefault();if(!editor.current||uploadLock.current){setError('첨부 저장이 끝나면 다시 붙여넣어 주세요.');return}const html=e.clipboardData.getData('text/html');if(!html&&e.clipboardData.files.length){files(Array.from(e.clipboardData.files));return}const parsed=parsePaste(html,e.clipboardData.getData('text/plain'));if(editor.current.querySelectorAll('img,video,[data-status]').length+parsed.pending.length>20){setError('첨부는 최대 20개까지 첨부할 수 있어요.');return}insertFragment(editor.current,parsed.fragment);dirty.current=true;if(parsed.pending.length)void run(parsed.pending.map(p=>({node:p.node,value:p.url,kind:p.kind})))}}
onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();files(Array.from(e.dataTransfer.files))}}/>{previewLinks.length>0&&<section className="link-previews"><p className="subtext">링크 미리보기</p>{[...new Set(previewLinks)].map(url=><LinkCard key={url} url={url} create/>)}</section>}<div className="field"><label htmlFor="nickname">닉네임</label><input id="nickname" className="field-input" placeholder="이 글에 표시할 이름" maxLength={24} value={nickname} onChange={e=>{setNickname(e.target.value);dirty.current=true}}/></div><div className="field"><label htmlFor="source">출처 <span style={{fontWeight:400,color:'#9698aa'}}>선택</span></label><input id="source" className="field-input" type="url" placeholder="원본 게시글 주소 https://…" value={source} onChange={e=>{setSource(e.target.value);dirty.current=true}}/></div>{uploading&&<p className="status" role="status"><Upload style={{display:'inline'}}/> 첨부 저장 중…</p>}{status&&!uploading&&<p className="status" role="status"><Check style={{display:'inline'}}/> {status}</p>}{error&&<p className="status error" role="alert">{error}</p>}<div className="form-actions"><p className="subtext" style={{margin:0}}>공유할 수 있는 콘텐츠만 올려 주세요.<br/>{editId?'수정 내용은 등록 시 반영돼요.':'작성 중인 글은 이 기기에 임시 저장돼요.'}</p><button className="primary" disabled={busy||uploading||!ready} onClick={submit}><Send/>{busy?'등록 중…':editId?'수정 완료':'등록하기'}</button></div></div></Shell>}

